style.css:
/* Hello Kitty Skyward Pink Theme */

/* Background */
html, body {
  background: linear-gradient(180deg,#ffd6ec,#ffc0e6,#ffb3e0,#ffe6f5) !important;
  color: #ff4fa3 !important;
  font-family: "Comic Sans MS", "Poppins", sans-serif !important;
}

/* Cloud glow overlay */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background:
    radial-gradient(circle at 20% 30%, rgba(255,255,255,0.7), transparent 40%),
    radial-gradient(circle at 70% 20%, rgba(255,255,255,0.6), transparent 40%),
    radial-gradient(circle at 50% 70%, rgba(255,255,255,0.5), transparent 40%);
  pointer-events: none;
  z-index: -1;
}

/* Buttons */
button {
  background: #ff9bd4 !important;
  border-radius: 15px !important;
  border: 2px solid #ff6fbf !important;
  color: white !important;
  box-shadow: 0 0 10px rgba(255,150,200,0.7);
}

/* Button hover */
button:hover {
  background: #ff6fbf !important;
  transform: scale(1.05);
}

/* Links */
a {
  color: #ff4fa3 !important;
}

a:hover {
  color: #ff85c7 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: #ffe6f5;
}

::-webkit-scrollbar-thumb {
  background: #ff9bd4;
  border-radius: 10px;
}

/* Panels */
div, section, article {
  background: rgba(255,255,255,0.65) !important;
  border-radius: 20px !important;
  backdrop-filter: blur(6px);
}
